// Email validation pipeline: format → disposable domain blocklist → Abstract API deliverability.
// Each layer short-circuits on failure, so expensive checks only run after cheaper ones pass.

import { log } from "@repo/observability/log";
import disposableDomains from "disposable-email-domains";
import { z } from "zod";

const disposableSet = new Set(disposableDomains);

/**
 * The one shape an address takes before it is compared, stored or deleted:
 * trimmed and lowercased. Addresses are case-insensitive in practice and
 * mobile keyboards capitalise the first letter, so the same person would
 * otherwise hold one row per casing.
 */
export function normalizeEmail(input: unknown): string {
  return typeof input === "string" ? input.trim().toLowerCase() : "";
}

/**
 * Must stay in step with the `email_ci` index on `subscribers` (unique,
 * `{ locale: "en", strength: 2 }`). A query only matches case-insensitively
 * when it passes the collation the index was built with; a plain equality
 * lookup uses `email_1` and sees exact bytes only.
 */
export const EMAIL_COLLATION = { locale: "en", strength: 2 } as const;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export type ValidationFailureReason =
  | "invalid_format"
  | "disposable"
  | "undeliverable";

export type ValidationResult =
  | { valid: true }
  | { valid: false; reason: ValidationFailureReason };

const TRUSTED_DOMAINS = new Set([
  "gmail.com",
  "googlemail.com",
  "outlook.com",
  "hotmail.com",
  "live.com",
  "yahoo.com",
  "icloud.com",
  "me.com",
  "mac.com",
  "protonmail.com",
  "proton.me",
  "fastmail.com",
  "hey.com",
  "aol.com",
  "zoho.com",
  "yandex.com",
  "mail.com",
]);

const AbstractApiResponse = z.object({
  deliverability: z.enum(["DELIVERABLE", "UNDELIVERABLE", "RISKY", "UNKNOWN"]),
});

export function isDisposableEmail(email: string): boolean {
  const domain = email.split("@")[1]?.toLowerCase();
  if (!domain) {
    return false;
  }
  return disposableSet.has(domain);
}

export async function checkEmailDeliverability(
  email: string
): Promise<ValidationResult> {
  // Dynamic import: Bun's mock.module does not intercept @/ path aliases in
  // transitive dynamic imports, so the test preload sets process.env fallbacks
  // to keep the real env.ts from failing when loaded outside the mock scope.
  const { env } = await import("@/env");
  const apiKey = env.ABSTRACT_API_KEY;
  const domain = email.split("@")[1]?.toLowerCase();

  if (!apiKey) {
    return { valid: true };
  }

  if (!domain || TRUSTED_DOMAINS.has(domain)) {
    return { valid: true };
  }

  try {
    const response = await fetch(
      `https://emailvalidation.abstractapi.com/v1/?api_key=${apiKey}&email=${encodeURIComponent(email)}`,
      { signal: AbortSignal.timeout(5000) }
    );

    if (!response.ok) {
      log.error(
        `Email deliverability API returned HTTP ${response.status}. Failing open.`
      );
      return { valid: true };
    }

    const raw = await response.json();
    const parsed = AbstractApiResponse.safeParse(raw);

    if (!parsed.success) {
      log.error(
        `Unexpected Abstract API response shape: ${JSON.stringify(raw)}`
      );
      return { valid: true };
    }

    if (parsed.data.deliverability === "UNDELIVERABLE") {
      return { reason: "undeliverable", valid: false };
    }

    return { valid: true };
  } catch (error) {
    if (error instanceof DOMException && error.name === "TimeoutError") {
      log.warn("Email deliverability check timed out. Failing open.");
    } else {
      log.error(
        `Email deliverability check failed: ${error instanceof Error ? error.message : String(error)}`
      );
    }
    return { valid: true };
  }
}

/** The cheap half: shape and the disposable blocklist, no network. */
export function validateEmailFormat(email: string): ValidationResult {
  if (
    !email ||
    typeof email !== "string" ||
    email.length > 254 ||
    !EMAIL_RE.test(email)
  ) {
    return { reason: "invalid_format", valid: false };
  }

  if (isDisposableEmail(email)) {
    return { reason: "disposable", valid: false };
  }

  return { valid: true };
}

export async function validateEmail(email: string): Promise<ValidationResult> {
  const format = validateEmailFormat(email);
  return format.valid ? await checkEmailDeliverability(email) : format;
}
